// idt-package-remaining-api: /api/packages — Task 1 of the Package Desk spec (2026-09-06).
// Status is computed server-side at creation and re-derived by /api/punches on every redeem —
// never trusted from the client. "empty" at 0 remaining, "low" at <= 2, "ok" otherwise.
let packageStore = [];
let pkgCounter = 1;
function generatePackageId() { return `pkg-${pkgCounter++}`; }
function derivePackageStatus(remainingPunches) {
  if (remainingPunches <= 0) return "empty";
  if (remainingPunches <= 2) return "low";
  return "ok";
}
router.get("/packages", (_req, res) => {
  res.status(200).json(packageStore);
});
router.post("/packages", (req, res) => {
  if (!req.body.client || !req.body.service || req.body.totalPunches === undefined) {
    return res.status(400).json({ error: "client, service, and totalPunches are required." });
  }
  const totalPunches = Number(req.body.totalPunches);
  const record = {
    id: generatePackageId(),
    client: req.body.client,
    service: req.body.service,
    totalPunches,
    remainingPunches: totalPunches,
    status: derivePackageStatus(totalPunches),
  };
  packageStore.push(record);
  res.status(201).json(record);
});


// idt-punch-redeem-api: /api/punches — Task 2 of the Package Desk spec (2026-09-06). Redeeming a
// visit is a transaction against the SAME packageStore Task 1 owns, not a second copy of it: 400
// if packageId is missing, 404 if it doesn't match a real package, 409 if that package is already
// empty — checked before anything is written, so a depleted card can never go negative.
let punchLogs = [];
let punchCounter = 1;
function generatePunchId() { return `punch-${punchCounter++}`; }
router.get("/punches", (_req, res) => {
  res.status(200).json(punchLogs);
});
router.post("/punches", (req, res) => {
  if (!req.body.packageId) {
    return res.status(400).json({ error: "packageId is required" });
  }
  const targetPackage = packageStore.find((pkg) => pkg.id === req.body.packageId);
  if (!targetPackage) {
    return res.status(404).json({ error: "Package not found" });
  }
  if (targetPackage.remainingPunches <= 0) {
    return res.status(409).json({ error: "Cannot redeem visit: package is already empty." });
  }

  targetPackage.remainingPunches -= 1;
  targetPackage.status = derivePackageStatus(targetPackage.remainingPunches);

  const log = {
    id: generatePunchId(),
    packageId: targetPackage.id,
    redeemedAt: new Date().toISOString(),
  };
  punchLogs.push(log);
  res.status(201).json({ log, package: targetPackage });
});

export default router;
